type Compare string

const (
	ComparePreviousYear Compare = "previous_year"
	CompareAllYears     Compare = "all_years"
)

// AllValues returns all Compare values.
func (Compare) AllValues() []Compare {
	return []Compare{
		ComparePreviousYear,
		CompareAllYears,
	}
}

// MarshalText implements encoding.TextMarshaler.
func (s Compare) MarshalText() ([]byte, error) {
	switch s {
	case ComparePreviousYear:
		return []byte(s), nil
	case CompareAllYears:
		return []byte(s), nil
	default:
		return nil, errors.Errorf("invalid value: %q", s)
	}
}

// UnmarshalText implements encoding.TextUnmarshaler.
func (s *Compare) UnmarshalText(data []byte) error {
	switch Compare(data) {
	case ComparePreviousYear:
		*s = ComparePreviousYear
		return nil
	case CompareAllYears:
		*s = CompareAllYears
		return nil
	default:
		return errors.Errorf("invalid value: %q", data)
	}
}

