// `pvoutput_export` pushes instead of pulling: every run uploads new 5-minute status (power and energy
// of the day) and the daily output of finished days to PVOutput. `solarlog_hosted` creates an FTP
// account on noonside's own FTP server (SFTPGo) that the Solar-Log uploads its export to (see
// `upload`); it takes no config and needs `features.hosted_ftp`. It is imported after each upload, not
// on `poll_interval_s`.
// Ref: #/components/schemas/DataSourceKind
type DataSourceKind string

const (
	DataSourceKindSolarlogRemote DataSourceKind = "solarlog_remote"
	DataSourceKindSolarlogHosted DataSourceKind = "solarlog_hosted"
	DataSourceKindPvoutputExport DataSourceKind = "pvoutput_export"
)

// AllValues returns all DataSourceKind values.
func (DataSourceKind) AllValues() []DataSourceKind {
	return []DataSourceKind{
		DataSourceKindSolarlogRemote,
		DataSourceKindSolarlogHosted,
		DataSourceKindPvoutputExport,
	}
}

// MarshalText implements encoding.TextMarshaler.
func (s DataSourceKind) MarshalText() ([]byte, error) {
	switch s {
	case DataSourceKindSolarlogRemote:
		return []byte(s), nil
	case DataSourceKindSolarlogHosted:
		return []byte(s), nil
	case DataSourceKindPvoutputExport:
		return []byte(s), nil
	default:
		return nil, errors.Errorf("invalid value: %q", s)
	}
}

// UnmarshalText implements encoding.TextUnmarshaler.
func (s *DataSourceKind) UnmarshalText(data []byte) error {
	switch DataSourceKind(data) {
	case DataSourceKindSolarlogRemote:
		*s = DataSourceKindSolarlogRemote
		return nil
	case DataSourceKindSolarlogHosted:
		*s = DataSourceKindSolarlogHosted
		return nil
	case DataSourceKindPvoutputExport:
		*s = DataSourceKindPvoutputExport
		return nil
	default:
		return errors.Errorf("invalid value: %q", data)
	}
}

