type ListAlertsState string

const (
	ListAlertsStateOpen ListAlertsState = "open"
	ListAlertsStateAll  ListAlertsState = "all"
)

// AllValues returns all ListAlertsState values.
func (ListAlertsState) AllValues() []ListAlertsState {
	return []ListAlertsState{
		ListAlertsStateOpen,
		ListAlertsStateAll,
	}
}

// MarshalText implements encoding.TextMarshaler.
func (s ListAlertsState) MarshalText() ([]byte, error) {
	switch s {
	case ListAlertsStateOpen:
		return []byte(s), nil
	case ListAlertsStateAll:
		return []byte(s), nil
	default:
		return nil, errors.Errorf("invalid value: %q", s)
	}
}

// UnmarshalText implements encoding.TextUnmarshaler.
func (s *ListAlertsState) UnmarshalText(data []byte) error {
	switch ListAlertsState(data) {
	case ListAlertsStateOpen:
		*s = ListAlertsStateOpen
		return nil
	case ListAlertsStateAll:
		*s = ListAlertsStateAll
		return nil
	default:
		return errors.Errorf("invalid value: %q", data)
	}
}

