// Ref: #/components/schemas/Overview
type Overview struct {
	Period Period    `json:"period"`
	Date   time.Time `json:"date"`
	// Earliest day with data or the commissioning date.
	FirstDate  time.Time `json:"first_date"`
	RangeStart time.Time `json:"range_start"`
	RangeEnd   time.Time `json:"range_end"`
	// A date in the previous period.
	PrevDate time.Time `json:"prev_date"`
	// A date in the next period.
	NextDate OptDate      `json:"next_date"`
	Unit     OverviewUnit `json:"unit"`
	// Start of each bucket; series values align with this array.
	Timestamps []time.Time `json:"timestamps"`
	Total      []float64   `json:"total"`
	// Expected energy per bucket (month/year/total only): from the weather where known, otherwise from the
	// monthly targets (see summary.target_source).
	Target []float64 `json:"target"`
	// Performance ratio in % per bucket (month/year/total only): energy of the complete past days with
	// weather data ÷ (irradiation on the panel planes × kWp); null without them.
	PerformanceRatio []NilFloat64 `json:"performance_ratio"`
	// Weather-based expected power of the shown inverters (day only), as mean values at the middle of each
	// 15-minute (before 2022: hourly) interval.
	Expected []ExpectedPoint `json:"expected"`
	// Day only, with a price zone: the day's day-ahead prices (hourly before October 2025, then 15
	// minutes).
	Prices []PricePoint `json:"prices"`
	// Provider of the prices.
	PricesSource OptString `json:"prices_source"`
	// Month/year/total only; per bucket, whether it contains manually corrected days.
	Corrected []bool           `json:"corrected"`
	Series    []InverterSeries `json:"series"`
	// With `compare` (month and year only): energy (kWh) of the shown inverters in the same buckets of
	// earlier years, newest first. A month's days align by day of the month; null where the day does not
	// exist or lies before the first data.
	Comparison []ComparisonSeries `json:"comparison"`
	Summary    OverviewSummary    `json:"summary"`
	Inverters  []InverterSummary  `json:"inverters"`
}

