// Ref: #/components/schemas/OverviewSummary
type OverviewSummary struct {
	EnergyKwh           float64    `json:"energy_kwh"`
	Revenue             float64    `json:"revenue"`
	Currency            string     `json:"currency"`
	SpecificYieldKwhKwp OptFloat64 `json:"specific_yield_kwh_kwp"`
	// Peak power (day) or best bucket energy.
	MaxValue OptFloat64  `json:"max_value"`
	MaxAt    OptDateTime `json:"max_at"`
	// Expected energy for the whole period.
	TargetKwh OptFloat64 `json:"target_kwh"`
	// Expected energy until now.
	TargetToDateKwh OptFloat64 `json:"target_to_date_kwh"`
	// Energy / target_to_date.
	ActualPct OptFloat64 `json:"actual_pct"`
	// Weather: at least partly from the weather (Open-Meteo); targets: only the monthly targets.
	TargetSource OptOverviewSummaryTargetSource `json:"target_source"`
	// Irradiation on the panel planes (kWp-weighted) of the days the performance ratio covers: until now
	// for today, otherwise the complete past days with weather data.
	IrradiationKwhM2 OptFloat64 `json:"irradiation_kwh_m2"`
	// Energy ÷ (irradiation × kWp) over the same days; missing without weather data.
	PerformanceRatioPct OptFloat64 `json:"performance_ratio_pct"`
	// Total view only: change of the yearly performance ratio in percentage points per year (least squares
	// over complete years, at least three), a sign of degradation.
	PerformanceRatioTrendPct OptFloat64 `json:"performance_ratio_trend_pct"`
	// With a price zone: energy produced while the day-ahead price was negative (from minute data; without
	// meters all of it counts as fed in). Missing without prices.
	NegativePriceKwh OptFloat64 `json:"negative_price_kwh"`
	// Hours with a negative price in the period.
	NegativePriceHours OptFloat64 `json:"negative_price_hours"`
	// With unpaid_at_negative_prices: revenue not paid for negative_price_kwh; `revenue` already leaves it
	// out.
	UnpaidRevenue OptFloat64 `json:"unpaid_revenue"`
	// The period's energy contains manually corrected days.
	Corrected            OptBool `json:"corrected"`
	Co2AvoidedKg         float64 `json:"co2_avoided_kg"`
	LifetimeEnergyKwh    float64 `json:"lifetime_energy_kwh"`
	LifetimeCo2AvoidedKg float64 `json:"lifetime_co2_avoided_kg"`
}

